output.sparql:
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX wikibase: <http://wikiba.se/ontology#>
SELECT ?player WHERE {
  ?player wdt:P1127 wd:Q15022551;  # center position
          wdt:P166 wd:Q513736;   # NBA MVP award
          wdt:P196 wd:Q495029;   # played in NBA
          wdt:P2048 ?height;
  ?height wikibase:quantityAmount ?heightValue;
  FILTER(?heightValue < 208.28)  # 6'10" = 208.28 cm
}

